+	if (*count >= MAX_MCS) {
+		ksft_print_msg("Maximum MC count exceeded\n");
+		return -1;
+	}
+
+	mc_counters_config[*count].type = type;
+	mc_counters_config[*count].event = 0xa;
+	mc_counters_config[*count].umask = 0x1;
