 	dma_addr_t direct_tx_cpl_dma;
 	u32 direct_rx_prod;
@@ -222,6 +224,7 @@ struct ntb_transport_qp {
 	u32 direct_session;
 	u32 direct_peer_session;
 	enum ntb_direct_state direct_state;
+	bool direct_tx_failed;
