diff --git a/drivers/net/phy/ax88796b.c b/drivers/net/phy/ax88796b.c
index f20ddf64914993f7097070d1f56c1103ec1e40e8..1298e46ad9e1609a5907b20dd8f1827c8bd221d1 100644
